import base64,datetime,hashlib,json,os,pathlib,socket,subprocess,sys,tempfile
assert os.geteuid()==0 and socket.gethostname().split('.')[0]=='k8s-control01'
os.umask(0o077)
FILES={'runtime.py': '', 'guard.py': '', 'input.json': ''}
out=pathlib.Path(tempfile.mkdtemp(prefix='if05c-20261008-',dir='/root'))
hashes={}
for name,b64 in FILES.items():
 b=base64.b64decode(b64);(out/name).write_bytes(b);hashes[name]=hashlib.sha256(b).hexdigest()
p=subprocess.run([sys.executable,'-B',str(out/'runtime.py'),'check',str(out)],capture_output=True,timeout=170)
(out/'preflight.stdout').write_bytes(p.stdout);(out/'preflight.stderr').write_bytes(p.stderr)
print(json.dumps({'path':str(out),'hashes':hashes,'rc':p.returncode,'status':json.loads((out/'status.json').read_text()) if (out/'status.json').exists() else None,'stderr':p.stderr.decode(errors='replace')}))
